create table `product_variants` (`id` bigint unsigned not null auto_increment primary key, `product_id` bigint unsigned not null, `name` varchar(255) not null, `image_path` varchar(255) null, `price_yuan` decimal(12, 2) not null, `compare_price_yuan` decimal(12, 2) null, `weight_grams` int unsigned not null, `status` varchar(20) not null default 'available', `sort_order` smallint unsigned not null default '0', `created_at` timestamp null, `updated_at` timestamp null) default character set utf8mb4 collate 'utf8mb4_unicode_ci';
